class Vault {
  readonly #store: Store;      // hard private: unreachable even via vault['#store']
  readonly #policy: Policy;
  constructor(store: Store, policy: Policy) { this.#store = store; this.#policy = policy; }
  read(subject: Subject, id: Id): Record {
    if (!this.#policy.allows(subject, id)) throw new Error(`denied: ${id}`);
    return this.#store.get(id);   // every exported path passes this check
  }
}
